import{_ as a,o as d,c as n,a6 as t}from"./chunks/framework.BBdhcoHf.js";const h=JSON.parse('{"title":"Package Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/packages.md","filePath":"architecture/packages.md","lastUpdated":1772916561000}'),i={name:"architecture/packages.md"};function r(s,e,o,c,l,p){return d(),n("div",null,[...e[0]||(e[0]=[t(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /architecture/packages.md for this page in Markdown format</div><h1 id="package-architecture" tabindex="-1">Package Architecture <a class="header-anchor" href="#package-architecture" aria-label="Permalink to “Package Architecture”">​</a></h1><p>Package boundaries and dependency direction for the current Sideband workspace.</p><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to “Design Principles”">​</a></h2><ol><li>Core remains topology- and transport-agnostic.</li><li>Session cryptography is isolated from runtime/transport.</li><li>Public package APIs prioritize correctness and typing over feature breadth.</li><li>Higher-level packages compose lower-level ones; lower layers never depend upward.</li></ol><h2 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to “Terminology”">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Context</th><th>Meaning</th></tr></thead><tbody><tr><td>Cryptographic session</td><td><code>@sideband/secure-relay</code></td><td>Handshake state, traffic keys, sequence/replay state</td></tr><tr><td>Runtime connection</td><td><code>@sideband/runtime</code></td><td>Logical link over an attached transport</td></tr><tr><td>Peer session</td><td><code>@sideband/peer</code></td><td>SDK-level lifecycle abstraction over runtime + optional negotiator</td></tr></tbody></table><h2 id="layered-view" tabindex="-1">Layered View <a class="header-anchor" href="#layered-view" aria-label="Permalink to “Layered View”">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Package(s)</th><th>Responsibility</th></tr></thead><tbody><tr><td>Layer 0: Wire Contract</td><td><code>@sideband/protocol</code></td><td>Canonical frame/types/constants + codecs</td></tr><tr><td>Layer 1: I/O</td><td><code>@sideband/transport</code>, <code>@sideband/transport-ws</code></td><td>Transport ABI + WebSocket transport</td></tr><tr><td>Layer 2: Message Semantics</td><td><code>@sideband/rpc</code></td><td>Typed RPC envelope/codec model</td></tr><tr><td>Layer 3: Coordination</td><td><code>@sideband/runtime</code></td><td>Peer lifecycle, routing, transport attachment</td></tr><tr><td>Layer 4: Session Crypto</td><td><code>@sideband/secure-relay</code></td><td>SBRP handshake/encryption/replay protection</td></tr><tr><td>Layer 5: SDK</td><td><code>@sideband/peer</code></td><td>User-facing composition of runtime, transport, negotiators</td></tr><tr><td>Tooling</td><td><code>sideband</code>, <code>@sideband/testing</code></td><td>Developer CLI and test helpers</td></tr></tbody></table><p><code>@sideband/runtime</code> and <code>@sideband/secure-relay</code> are sibling layers: neither depends on the other.</p><h2 id="package-reference" tabindex="-1">Package Reference <a class="header-anchor" href="#package-reference" aria-label="Permalink to “Package Reference”">​</a></h2><h3 id="sideband-protocol" tabindex="-1"><code>@sideband/protocol</code> <a class="header-anchor" href="#sideband-protocol" aria-label="Permalink to “@sideband/protocol”">​</a></h3><ul><li>Provides: canonical protocol types/constants, frame codecs, type guards.</li><li>Does not provide: I/O, transport implementations, cryptography, runtime/session logic.</li><li>Runtime dependencies: none.</li></ul><h3 id="sideband-transport" tabindex="-1"><code>@sideband/transport</code> <a class="header-anchor" href="#sideband-transport" aria-label="Permalink to “@sideband/transport”">​</a></h3><ul><li>Provides: transport interfaces and shared transport utilities.</li><li>Does not provide: concrete network transport stacks, runtime/session logic.</li><li>Runtime dependencies: <code>@sideband/protocol</code>.</li></ul><h3 id="sideband-transport-ws" tabindex="-1"><code>@sideband/transport-ws</code> <a class="header-anchor" href="#sideband-transport-ws" aria-label="Permalink to “@sideband/transport-ws”">​</a></h3><ul><li>Provides: browser + Node/Bun WebSocket transport implementation.</li><li>Does not provide: runtime orchestration or cryptographic session behavior.</li><li>Runtime dependencies: <code>@sideband/protocol</code>, <code>@sideband/transport</code>, <code>ws</code>.</li></ul><h3 id="sideband-rpc" tabindex="-1"><code>@sideband/rpc</code> <a class="header-anchor" href="#sideband-rpc" aria-label="Permalink to “@sideband/rpc”">​</a></h3><ul><li>Provides: typed RPC envelope model and JSON codec helpers.</li><li>Does not provide: transport delivery or encryption.</li><li>Runtime dependencies: <code>@sideband/protocol</code>.</li></ul><h3 id="sideband-runtime" tabindex="-1"><code>@sideband/runtime</code> <a class="header-anchor" href="#sideband-runtime" aria-label="Permalink to “@sideband/runtime”">​</a></h3><ul><li>Provides: transport attachment, peer lifecycle, message routing, middleware hooks.</li><li>Does not provide: concrete transport implementations or cryptographic session primitives.</li><li>Runtime dependencies: <code>@sideband/protocol</code>, <code>@sideband/transport</code>, <code>@sideband/rpc</code>.</li></ul><h3 id="sideband-secure-relay" tabindex="-1"><code>@sideband/secure-relay</code> <a class="header-anchor" href="#sideband-secure-relay" aria-label="Permalink to “@sideband/secure-relay”">​</a></h3><ul><li>Provides: SBRP handshake, key derivation, frame codecs, encryption/decryption, replay protection.</li><li>Does not provide: WebSocket/network I/O, token issuance/validation, relay server behavior.</li><li>Runtime dependencies: <code>@noble/ciphers</code>, <code>@noble/curves</code>, <code>@noble/hashes</code>.</li></ul><h3 id="sideband-peer" tabindex="-1"><code>@sideband/peer</code> <a class="header-anchor" href="#sideband-peer" aria-label="Permalink to “@sideband/peer”">​</a></h3><ul><li>Provides: high-level SDK that composes runtime + transport + optional relay negotiators.</li><li>Does not provide: base wire contract definitions or low-level crypto primitives.</li><li>Runtime dependencies: <code>@sideband/protocol</code>, <code>@sideband/rpc</code>, <code>@sideband/runtime</code>, <code>@sideband/transport</code>, <code>@sideband/transport-ws</code>.</li><li>Optional peer dependency: <code>@sideband/secure-relay</code> (for SBRP negotiators).</li></ul><h3 id="sideband-cloud" tabindex="-1"><code>@sideband/cloud</code> <a class="header-anchor" href="#sideband-cloud" aria-label="Permalink to “@sideband/cloud”">​</a></h3><ul><li>Provides: relay.sideband.cloud integration — <code>connect()</code> (client) and <code>listen()</code> (daemon). <code>listen()</code> returns <code>CloudServer</code> (extends <code>PeerServer</code>) with <code>daemonId</code>, <code>relayUrl</code>, and <code>createQuickConnect()</code>. Also exports <code>renewPresenceToken</code> and <code>extractDaemonIdFromToken</code>.</li><li>Does not provide: protocol definitions or cryptographic primitives.</li><li>Runtime dependencies: <code>@sideband/peer</code>, <code>@sideband/secure-relay</code>, <code>@sideband/transport-ws</code>.</li></ul><h3 id="sideband" tabindex="-1"><code>sideband</code> <a class="header-anchor" href="#sideband" aria-label="Permalink to “sideband”">​</a></h3><ul><li>Provides: daemon CLI (<code>npx sideband</code>) — connects to relay.sideband.cloud and prints a Quick Connect URL for zero-infrastructure remote access. Wraps <code>@sideband/cloud</code>&#39;s <code>listen()</code>.</li><li>Runtime dependencies: <code>@sideband/cloud</code>, <code>@sideband/secure-relay</code>.</li></ul><h3 id="sideband-testing" tabindex="-1"><code>@sideband/testing</code> <a class="header-anchor" href="#sideband-testing" aria-label="Permalink to “@sideband/testing”">​</a></h3><ul><li>Provides: shared test fixtures/fakes/helpers for workspace packages.</li><li>Runtime dependencies: package-local only; intended for test-only usage.</li></ul><h2 id="current-workspace-packages" tabindex="-1">Current Workspace Packages <a class="header-anchor" href="#current-workspace-packages" aria-label="Permalink to “Current Workspace Packages”">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Role</th></tr></thead><tbody><tr><td><code>@sideband/protocol</code></td><td>Wire contract</td></tr><tr><td><code>@sideband/transport</code></td><td>Transport ABI</td></tr><tr><td><code>@sideband/transport-ws</code></td><td>WebSocket transport</td></tr><tr><td><code>@sideband/rpc</code></td><td>RPC envelope layer</td></tr><tr><td><code>@sideband/runtime</code></td><td>Runtime coordination engine</td></tr><tr><td><code>@sideband/secure-relay</code></td><td>SBRP cryptographic session layer</td></tr><tr><td><code>@sideband/peer</code></td><td>User-facing SDK</td></tr><tr><td><code>@sideband/cloud</code></td><td>relay.sideband.cloud integration</td></tr><tr><td><code>sideband</code></td><td>Daemon CLI (Quick Connect)</td></tr><tr><td><code>@sideband/testing</code></td><td>Test helpers</td></tr></tbody></table><h2 id="dependency-direction" tabindex="-1">Dependency Direction <a class="header-anchor" href="#dependency-direction" aria-label="Permalink to “Dependency Direction”">​</a></h2><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@sideband/protocol</span></span>
<span class="line"><span>├─&gt; @sideband/transport ──&gt; @sideband/transport-ws</span></span>
<span class="line"><span>├─&gt; @sideband/rpc</span></span>
<span class="line"><span>├─&gt; @sideband/runtime</span></span>
<span class="line"><span>└─&gt; @sideband/peer</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@sideband/transport ──&gt; @sideband/runtime</span></span>
<span class="line"><span>@sideband/transport ──&gt; @sideband/peer</span></span>
<span class="line"><span>@sideband/rpc ──&gt; @sideband/runtime</span></span>
<span class="line"><span>@sideband/rpc ──&gt; @sideband/peer</span></span>
<span class="line"><span>@sideband/runtime ──&gt; @sideband/peer</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@sideband/secure-relay (optional peer dependency of @sideband/peer)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@sideband/peer ──&gt; @sideband/cloud</span></span>
<span class="line"><span>@sideband/secure-relay ──&gt; @sideband/cloud</span></span>
<span class="line"><span>@sideband/transport-ws ──&gt; @sideband/cloud</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@sideband/cloud ──&gt; sideband (cli)</span></span>
<span class="line"><span>@sideband/secure-relay ──&gt; sideband (cli)</span></span></code></pre></div><h2 id="relay-composition-sbrp-sbp" tabindex="-1">Relay Composition (SBRP + SBP) <a class="header-anchor" href="#relay-composition-sbrp-sbp" aria-label="Permalink to “Relay Composition (SBRP + SBP)”">​</a></h2><p>In relay mode, SBRP transports encrypted SBP payloads. Integration ownership is split:</p><ol><li><code>@sideband/transport-ws</code>: WebSocket transport.</li><li><code>@sideband/secure-relay</code>: handshake + payload crypto.</li><li><code>@sideband/protocol</code>: inner application frames.</li><li><code>@sideband/rpc</code>: request/response envelopes inside protocol messages.</li><li><code>@sideband/peer</code>: user-facing orchestration.</li></ol><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><ul><li><code>@sideband/protocol</code> is the canonical wire contract.</li><li><code>@sideband/runtime</code> coordinates transport and message flow.</li><li><code>@sideband/secure-relay</code> is cryptographic/session logic only.</li><li><code>@sideband/peer</code> composes runtime with optional relay negotiators.</li></ul>`,40)])])}const u=a(i,[["render",r]]);export{h as __pageData,u as default};
